62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** An owner's postcode, when supplied, must be exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
84	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
91	     * named logger keeps them addressable independently of the class's diagnostic logging.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Maximum number of owners a single city may contain. A create that would take the owner's city
97	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
98	     */
99	    private static final int CITY_OWNER_LIMIT = 50;
100	
101	    /**
102	     * Maximum number of owners that may be registered on a single day. A create that would take the
103	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
104	     * have already been created that day - is rejected with a 429.
105	     */
106	    private static final int DAILY_OWNER_LIMIT = 100;
107	
108	    /**
109	     * Number of owners that must already have been created for a given day before the create
110	     * response flags a bulk sign-up. When more than this many owners already share a
111	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    private final ClinicService clinicService;
116	
117	    private final OwnerMapper ownerMapper;
118	
119	    private final PetMapper petMapper;
120	
121	    private final VisitMapper visitMapper;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper) {
127	        this.clinicService = clinicService;
128	        this.ownerMapper = ownerMapper;
129	        this.petMapper = petMapper;
130	        this.visitMapper = visitMapper;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
158	    }
159	
160	    /**
161	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
162	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
163	     * owner sign-ups.
164	     *
165	     * @param registrationDate the day to inspect, or {@code null}
166	     * @return {@code true} when more than the threshold of owners are registered on that day
167	     */
168	    private boolean isBulkSignupDay(LocalDate registrationDate) {
169	        return registrationDate != null
170	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
176	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
177	        validateRequiredFields(ownerFieldsDto);
178	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
182	        owner.setEmail(normalizeEmail(owner.getEmail()));
183	        validateRegistrationDate(owner.getRegistrationDate());
184	        if (owner.getRegistrationDate() == null) {
185	            owner.setRegistrationDate(LocalDate.now());
186	        }
187	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
188	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
189	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
190	        owner.setIdentityKey(buildIdentityKey(owner));
191	        if (!sharesHousehold) {
192	            rejectHouseholdDuplicate(owner.getHouseholdId());
193	        }
194	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
195	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
196	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
197	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
198	            throw new OwnerCityFullException(owner.getCity());
199	        }
200	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
201	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
202	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
203	        }
204	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
205	        owner.setCustomerCode(buildCustomerCode(owner));
206	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
207	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
208	        this.clinicService.saveOwner(owner);
209	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
210	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
211	            MembershipLevel.forOwner(owner));
212	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
213	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
214	        headers.setLocation(UriComponentsBuilder.newInstance()
215	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
216	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    /**
220	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
221	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
222	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
223	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
224	     * after normalization is still rejected.
225	     *
226	     * @param ownerFieldsDto the submitted owner fields
227	     */
228	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
229	        List<String> missingFields = new ArrayList<>();
230	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
231	            missingFields.add("firstName");
232	        }
233	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
234	            missingFields.add("lastName");
235	        }
236	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
237	            missingFields.add("address");
238	        }
239	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
240	            missingFields.add("city");
241	        }
242	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
243	            missingFields.add("telephone");
244	        }
245	        if (!missingFields.isEmpty()) {
246	            throw new MissingOwnerFieldsException(missingFields);
247	        }
248	    }
249	
250	    /**
251	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
252	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
253	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
254	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
255	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
256	     * whose {@code errors} array lists {@code postcode}.
257	     *
258	     * @param postcode the submitted postcode, or {@code null} when none was supplied
259	     * @param city the owner's city, whose region determines the acceptable postcode range
260	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
261	     */
262	    private void validatePostcode(String postcode, String city) {
263	        if (!StringUtils.hasText(postcode)) {
264	            return;
265	        }
266	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
267	            throw new InvalidOwnerFieldsException(List.of("postcode"));
268	        }
269	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
270	            throw new InvalidOwnerFieldsException(List.of("postcode"));
271	        }
272	    }
273	
274	    /**
275	     * Validates an owner's optional registration date. Registration date is optional, so a missing
276	     * value is accepted (the create later defaults it to the server date). When a value is supplied
277	     * it may not lie in the future: a date later than the server's current date is rejected with a
278	     * 400 whose {@code errors} array lists {@code registrationDate}.
279	     *
280	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
281	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
282	     */
283	    private void validateRegistrationDate(LocalDate registrationDate) {
284	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
285	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
286	        }
287	    }
288	
289	    /**
290	     * Rejects a submitted owner that would join a household which already has a member. Because the
291	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
292	     * existing owner sharing that id is the same household, so a second such owner is reported to the
293	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
294	     * {@code sharesHousehold}, in which case this check is not performed.
295	     *
296	     * @param householdId the derived household identifier of the owner about to be created
297	     */
298	    private void rejectHouseholdDuplicate(String householdId) {
299	        boolean duplicate = this.clinicService.findAllOwners().stream()
300	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
301	        if (duplicate) {
302	            throw new DuplicateOwnerIdentityException(householdId);
303	        }
304	    }
305	
306	    /**
307	     * Derives the owner's {@code identityKey}, formatted
308	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
309	     * and email have already been normalized. The household segment always carries the owner's
310	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
311	     * the same household automatically.
312	     *
313	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
314	     * @return the derived identity key
315	     */
316	    private String buildIdentityKey(Owner owner) {
317	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
318	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
319	    }
320	
321	    /**
322	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
323	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
324	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
325	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
326	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
327	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
328	     * postcode was supplied, since both owners must share one; when several existing owners match, the
329	     * earliest (lowest id) is used.
330	     *
331	     * @param owner the normalized owner about to be created, with its telephone already normalized
332	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
333	     */
334	    private Integer findPossibleDuplicate(Owner owner) {
335	        if (!StringUtils.hasText(owner.getPostcode())) {
336	            return null;
337	        }
338	        return this.clinicService.findAllOwners().stream()
339	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
340	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
341	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
342	            .map(Owner::getId)
343	            .filter(id -> id != null)
344	            .min(Integer::compareTo)
345	            .orElse(null);
346	    }
347	
348	    /**
349	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
350	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
351	     * address; the accepted value is lower-cased before it is stored and returned.
352	     *
353	     * @param email the raw email value submitted by the client, or {@code null}
354	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
355	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
356	     */
357	    private String normalizeEmail(String email) {
358	        if (!StringUtils.hasText(email)) {
359	            return email;
360	        }
361	        if (!EMAIL_PATTERN.matcher(email).matches()) {
362	            throw new InvalidOwnerFieldsException(List.of("email"));
363	        }
364	        String normalized = email.toLowerCase();
365	        String domain = normalized.substring(normalized.indexOf('@') + 1);
366	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
367	            throw new InvalidOwnerFieldsException(List.of("email"));
368	        }
369	        return normalized;
370	    }
371	
372	    /**
373	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
374	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
375	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
376	     *
377	     * @param owner the normalized owner about to be created
378	     * @return the assigned customer code
379	     */
380	    private String buildCustomerCode(Owner owner) {
381	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
382	        return CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
383	    }
384	
385	    /**
386	     * Counts how many owners already exist that share the supplied first and last name, compared
387	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
388	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
389	     *
390	     * @param firstName the submitted owner's first name
391	     * @param lastName the submitted owner's last name
392	     * @return the number of existing owners with the same first and last name, ignoring case
393	     */
394	    private int countNamesakes(String firstName, String lastName) {
395	        return (int) this.clinicService.findAllOwners().stream()
396	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
397	                && lastName.equalsIgnoreCase(existing.getLastName()))
398	            .count();
399	    }
400	
401	    /**
402	     * Counts how many existing owners already belong to the supplied household, identified by its
403	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
404	     * owner is added (this count plus one).
405	     *
406	     * @param householdId the normalized household identifier of the owner being created
407	     * @return the number of existing owners already sharing that {@code householdId}
408	     */
409	    private int countHouseholdMembers(String householdId) {
410	        return (int) this.clinicService.findAllOwners().stream()
411	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
412	            .count();
413	    }
414	
415	    /**
416	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
417	     * enforce the per-city capacity limit when a new owner is created.
418	     *
419	     * @param city the submitted owner's city
420	     * @return the number of existing owners in that city, ignoring case
421	     */
422	    private long countOwnersInCity(String city) {
423	        return this.clinicService.findAllOwners().stream()
424	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
425	            .count();
426	    }
427	
428	    /**
429	     * Counts how many owners have already been created on the supplied registration date. Used to
430	     * enforce the per-day capacity limit when a new owner is created.
431	     *
432	     * @param registrationDate the registration date of the owner being created
433	     * @return the number of existing owners already registered on that date
434	     */
435	    /**
436	     * Rolls a registration date forward to a business day. A registration date must fall on a
437	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
438	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
439	     * from the registration date (such as the membership number's year segment) and the daily
440	     * create-limit therefore use the adjusted date.
441	     *
442	     * @param date the effective registration date, whether supplied or defaulted to the server date
443	     * @return the same date when it is a weekday, otherwise the next Monday
444	     */
445	    private LocalDate toBusinessDay(LocalDate date) {
446	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
447	            date = date.plusDays(1);
448	        }
449	        return date;
450	    }
451	
452	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
453	        return this.clinicService.findAllOwners().stream()
454	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
455	            .count();
456	    }
457	
458	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
459	    @Override
460	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
461	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
462	        if (currentOwner == null) {
463	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
464	        }
465	        currentOwner.setAddress(ownerFieldsDto.getAddress());
466	        currentOwner.setCity(ownerFieldsDto.getCity());
467	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
468	        currentOwner.setLastName(ownerFieldsDto.getLastName());
469	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
470	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
471	        this.clinicService.saveOwner(currentOwner);
472	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
473	    }
474	
475	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
476	    @Transactional
477	    @Override
478	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
479	        Owner owner = this.clinicService.findOwnerById(ownerId);
480	        if (owner == null) {
