19	/**
20	 * Normalizes a submitted postal address into the canonical form that is stored for an owner and
21	 * compared when detecting duplicate households. Kept apart from {@link OwnerRestControllerV1} so the
22	 * request handler stays focused on orchestration while the rules for how an address is canonicalized
23	 * live in one place.
24	 *
25	 * <p>The rule trims leading and trailing whitespace, collapses every internal run of whitespace to a
26	 * single space, upper-cases the result and expands the common abbreviations {@code ST -> STREET},
27	 * {@code RD -> ROAD} and {@code AVE -> AVENUE} (each matched as a whole word). That upper-cased,
28	 * expanded value is what gets stored and returned, and it is the form every address comparison uses.
29	 */
30	final class AddressNormalizer {
31	
32	    private AddressNormalizer() {
33	    }
34	
35	    /**
36	     * Normalizes a raw address value for owner creation. The normalized value is what gets stored and
37	     * returned, and it is what household duplicate detection and the shared household id compare
38	     * against, so two inputs that canonicalize to the same value belong to the same household.
39	     *
40	     * <p>Leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
41	     * single space, the value is upper-cased, and the whole-word abbreviations {@code ST}, {@code RD}
42	     * and {@code AVE} are expanded to {@code STREET}, {@code ROAD} and {@code AVENUE}.
43	     *
44	     * @param address the raw address value submitted by the client, or {@code null}
45	     * @return the normalized address, or the empty string when {@code address} is {@code null} or blank
46	     */
47	    static String normalize(String address) {
48	        if (address == null) {
49	            return "";
50	        }
51	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
52	        if (collapsed.isEmpty()) {
53	            return "";
54	        }
55	        String[] tokens = collapsed.split(" ");
56	        StringBuilder sb = new StringBuilder(collapsed.length());
57	        for (int i = 0; i < tokens.length; i++) {
58	            if (i > 0) {
59	                sb.append(' ');
60	            }
61	            sb.append(expandAbbreviation(tokens[i]));
62	        }
63	        return sb.toString();
64	    }
65	
66	    /**
67	     * Expands a single upper-cased address token when it is one of the common abbreviations, leaving
68	     * every other token unchanged.
69	     *
70	     * @param token an upper-cased whitespace-delimited address token
71	     * @return the expanded word, or the original token when it is not a recognized abbreviation
72	     */
73	    private static String expandAbbreviation(String token) {
74	        switch (token) {
75	            case "ST":
76	                return "STREET";
77	            case "RD":
78	                return "ROAD";
79	            case "AVE":
80	                return "AVENUE";
81	            default:
82	                return token;
83	        }
84	    }
85	
86	}
