1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region), preferring the postcode: the region is
7	 * looked up by postcode range first, and only when the postcode is absent or in
8	 * no known range does it fall back to a fixed city-to-region table. This returns
9	 * the same region for the known cities but disambiguates cities that share a name.
10	 *
11	 * <p>Kept as a plain static helper - rather than a method on {@link OwnerMapper} -
12	 * so MapStruct does not mistake it for an implicit String-to-String property
13	 * mapping and apply it to unrelated fields.
14	 *
15	 * <p>Public, like its sibling {@link MembershipLevel}, so the single region table
16	 * can be reused wherever an owner's region is needed rather than being
17	 * duplicated - callers outside this package derive the region through
18	 * {@link #forPostcodeAndCity(String, String)} (or {@link #forCity(String)} when
19	 * only the city is available) instead of holding their own copy of the tables.
20	 */
21	public final class OwnerLocality {
22	
23	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
24	    private static final Map<String, String> CITY_REGION = Map.of(
25	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
26	
27	    /** Region -> inclusive 4-digit postcode range {low, high}. */
28	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
29	        "NSW", new int[] {2000, 2099},
30	        "VIC", new int[] {3000, 3099},
31	        "QLD", new int[] {4000, 4099});
32	
33	    private OwnerLocality() {
34	    }
35	
36	    /**
37	     * Returns the canonical region for the given owner, preferring the postcode:
38	     * the region is derived from the postcode range first, falling back to the
39	     * city-to-region table only when the postcode is absent or in no known range.
40	     *
41	     * @param postcode the owner's postcode, or {@code null} when none was supplied
42	     * @param city the owner's city
43	     * @return the derived locality (region)
44	     */
45	    public static String forPostcodeAndCity(String postcode, String city) {
46	        String region = forPostcode(postcode);
47	        return region != null ? region : forCity(city);
48	    }
49	
50	    /**
51	     * Returns the owner's locality (region) as recorded in its customer code, whose
52	     * leading segment (before the first {@code '-'}) is the region derived when the
53	     * owner was created. Deriving the locality from the customer code keeps it in step
54	     * with the region-and-hash identity rather than re-deriving it independently.
55	     *
56	     * @param customerCode the owner's customer code, formatted {@code <REGION>-<HASH8>}
57	     * @return the REGION segment of the customer code, or "UNKNOWN" when it is absent
58	     */
59	    public static String forCustomerCode(String customerCode) {
60	        if (customerCode == null) {
61	            return "UNKNOWN";
62	        }
63	        int dash = customerCode.indexOf('-');
64	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
65	    }
66	
67	    /**
68	     * Returns the canonical region for the given city, or "UNKNOWN" when the city
69	     * is not in the fixed table (or is {@code null}).
70	     *
71	     * @param city the owner's city
72	     * @return the derived locality (region)
73	     */
74	    public static String forCity(String city) {
75	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
76	    }
77	
78	    /**
79	     * Returns whether the given postcode falls within the postcode range of the
80	     * region derived from the city. A city whose region has no fixed range (locality
81	     * "UNKNOWN") accepts any postcode. A postcode that is absent or non-numeric is
82	     * treated as not matching a ranged region.
83	     *
84	     * <p>Callers validate a supplied postcode's four-digit shape separately; this
85	     * method only answers whether the value sits in the city's region range, so the
86	     * single region table is not duplicated at the call site.
87	     *
88	     * @param postcode the owner's postcode, or {@code null} when none was supplied
89	     * @param city the owner's city, whose region determines the acceptable range
90	     * @return {@code true} when the city's region has no fixed range, or the postcode
91	     *         lies within it
92	     */
93	    public static boolean postcodeMatchesCity(String postcode, String city) {
94	        int[] range = REGION_POSTCODES.get(forCity(city));
95	        if (range == null) {
96	            return true;
97	        }
98	        if (postcode == null) {
99	            return false;
100	        }
101	        int value;
102	        try {
103	            value = Integer.parseInt(postcode.trim());
104	        }
105	        catch (NumberFormatException e) {
106	            return false;
107	        }
108	        return value >= range[0] && value <= range[1];
109	    }
110	
111	    /**
112	     * Returns the region whose postcode range contains the given postcode, or
113	     * {@code null} when the postcode is missing, non-numeric or in no known range.
114	     */
115	    private static String forPostcode(String postcode) {
116	        if (postcode == null) {
117	            return null;
118	        }
119	        int value;
120	        try {
121	            value = Integer.parseInt(postcode.trim());
122	        }
123	        catch (NumberFormatException e) {
124	            return null;
125	        }
126	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
127	            int[] range = entry.getValue();
128	            if (value >= range[0] && value <= range[1]) {
129	                return entry.getKey();
130	            }
131	        }
132	        return null;
133	    }
134	
135	}
